from lib import *
S = SS('g75')
steps = [
    step("夏令时(用 macOS 的系统时区库)。纽约 2026-03-07 12:00,Add(24h) 得到 2026-03-08 13:00 EDT,AddDate(0,0,1) 得到 2026-03-08 12:00 EDT,两者相差 −1h。不存在的时刻(3 月 8 日 2:30,当天 2:00 直接跳到 3:00):time.Date 得到 2026-03-08 01:30 EST −0500。重复出现的时刻(11 月 1 日 1:30 出现两次):得到 2026-11-01 01:30 EDT −0400,是先出现的那次。纽约 3 月 8 日这一天有 23 小时,11 月 1 日有 25 小时。", t=tl(S(1)), done=lidx(S(1), 'Add(24h)', '23 小时'), mark=lidx(S(1), '不存在的时刻', '重复出现的时刻', '25 小时'), b=bars([['跳时日的小时数', 23, '23'], ['普通日', 24, '24'], ['回拨日', 25, '25']], 25, done=[1], mark=[0, 2]), kv=KV([['Add(24h) vs AddDate', '相差 1 小时'], ['不存在的时刻', '得到 01:30 EST(不是 03:30)'], ['重复的时刻', '得到先出现的 EDT'], ['跳时日 / 回拨日', '23 / 25 小时']], ['不存在的时刻'])),
    step("解析字符串的时区坑:time.Parse 解析不带时区的 \"2026-06-01 12:00:00\" 得到 UTC 的 2026-06-01T12:00:00Z,ParseInLocation(…, 上海) 得到 +08:00,两者相差 8 小时。time.Parse 解析带 EST 缩写的字符串:区名 \"EST\",偏移 0 秒(不是 −5 小时)。ParseInLocation(…, 纽约) 解析同一个字符串:区名 \"EDT\",偏移 −14400 秒(字符串里的 EST 没有生效)。layout \"2006-1-2\" 解析 \"2026-06-01\":没有报错。", t=tl(S(2)), done=lidx(S(2), 'ParseInLocation(…, 上海)'), mark=lidx(S(2), '偏移 0 秒', '偏移 -14400 秒', '2006-1-2'), kv=KV([['Parse 无时区', '按 UTC'], ['Parse 带 EST', '区名 EST,偏移 0'], ['ParseInLocation', '按给定的位置的实际规则'], ['layout 宽松', '\"2006-1-2\" 接受 \"06-01\"']], ['Parse 带 EST'])),
    step("LoadLocation 每次都读文件:time.LoadLocation(\"Asia/Shanghai\") 17498 ns/次、10 次分配;t.In(已加载的位置) 0 ns/次;t.Format(RFC3339) 34 ns/次。要在循环里用时区,加载一次存成变量。", t=tl(S(3)), mark=lidx(S(3), 'LoadLocation'), b=bars([['LoadLocation (ns)', 17498, '17498'], ['t.Format(RFC3339)', 34, '34'], ['t.In(已加载)', 0, '≈0']], 17498, mark=[0], done=[1, 2]), kv=KV([['LoadLocation', '17498 ns,10 次分配'], ['t.In', '0 ns'], ['做法', '启动时加载一次']], ['做法'])),
    step("TZ 环境变量决定 time.Local:TZ=\"\"(空串)和 TZ=\"UTC\" 时 time.Local 是 UTC;TZ=\"Asia/Shanghai\" 时是 Asia/Shanghai(现在 13:57 CST +0800);TZ=\"America/New_York\" 时是 America/New_York。", t=tl(S(4)), mark=lidx(S(4), 'TZ=\"\"', 'TZ=\"UTC\"', 'TZ=\"Asia/Shanghai\"'), kv=KV([['TZ 为空串', 'UTC'], ['TZ=Asia/Shanghai', 'time.Local = Asia/Shanghai'], ['含义', '部署环境的 TZ 会改变 Local']], ['含义'])),
    step("容器里没有 tzdata:把 linux/arm64 静态程序用 docker import 做成只有一个文件的镜像(没有 /usr/share/zoneinfo)。普通编译:time.LoadLocation(\"Asia/Shanghai\") 失败:unknown time zone Asia/Shanghai;加 -tags timetzdata 编译:成功(12:00 UTC 显示为 20:00 CST +0800)。二进制大小从 2.86 MB 增加到 3.25 MB,多 381 KiB。", t=tl(S(5)), done=lidx(S(5), '[-tags timetzdata]', '二进制大小'), mark=lidx(S(5), '[普通编译]'), b=bars([['普通编译 (MB)', 2.86, '2.86'], ['-tags timetzdata', 3.25, '3.25']], 3.25, done=[0, 1]), kv=KV([['没有 tzdata 的容器', 'LoadLocation 失败'], ['-tags timetzdata', '把数据库嵌入二进制,+381 KiB']], ['-tags timetzdata'])),
    step("文档:LoadLocation 按顺序查找时区库——ZONEINFO 环境变量指向的目录或未压缩 zip、类 Unix 系统的标准安装位置、$GOROOT/lib/time/zoneinfo.zip、以及被导入的 time/tzdata 包(如果有的话)。名字为 \"\" 或 \"UTC\" 返回 UTC,\"Local\" 返回 Local。", t=tl(S(6)), done=lidx(S(6), 'LoadLocation returns a Location'), kv=KV([['查找顺序', 'ZONEINFO → 系统目录 → GOROOT 的 zoneinfo.zip → time/tzdata'], ['特殊名字', '\"\"、UTC → UTC;Local → Local']], ['查找顺序'])),
]
A = mkartg('g75', 75, 'Go,时区,time.Location,夏令时,tzdata,真实验证,动画演示',
    '在 Go 1.27.1 里验证时区的坑:跨夏令时 Add(24h) 与 AddDate 差 1 小时,不存在的 2:30 得到 01:30 EST,重复的 1:30 取先出现的 EDT;Parse 不带时区按 UTC、带 EST 缩写偏移为 0;LoadLocation 每次 17498 ns;TZ 环境变量决定 Local;没有 tzdata 的容器里 LoadLocation 失败,-tags timetzdata 只多 381 KiB。',
    '时间相关的 bug 多半出在时区和夏令时上。这篇用真实运行验证几个典型问题:跨夏令时加一天、不存在和重复的时刻、字符串解析时的时区、LoadLocation 的代价,以及最容易在上线时才发现的:容器里没有时区数据库。',
    [('23 / 25 小时', '纽约 2026 年 3 月 8 日与 11 月 1 日这两天各有多少小时'), ('17498 ns', 'time.LoadLocation 一次的耗时(读文件),t.In 只要 0 ns'), ('+381 KiB', '加 -tags timetzdata 后二进制多出的大小,换来容器里能用 LoadLocation')],
    [('加一天不是加 24 小时', '<p>纽约 3 月 7 日 12:00 加 24 小时到了 3 月 8 日 13:00 EDT,而 <code>AddDate(0,0,1)</code> 是 12:00 EDT,差一个小时。跳时那天只有 23 小时,回拨那天有 25 小时。要“明天同一时刻”用 <code>AddDate</code>。</p>'),
     ('不存在和重复的时刻', '<p>3 月 8 日 2:30 并不存在,<code>time.Date</code> 得到 01:30 EST;11 月 1 日 1:30 出现两次,得到的是先出现的 EDT。文档本来就说这种情况下选哪个时区“不保证”,不要依赖。</p>'),
     ('解析要带位置', '<p><code>time.Parse</code> 对不带时区的字符串按 UTC,<code>ParseInLocation</code> 才按指定位置;带 <code>EST</code> 这类缩写时,<code>Parse</code> 并不会把它换算成 −5 小时(偏移 0 秒)。解析业务时间时优先用 <code>ParseInLocation</code>,最好用带数字偏移的 RFC3339。</p>'),
     ('LoadLocation 要缓存', '<p>每次 <code>LoadLocation</code> 约 17498 ns、10 次分配;加载后 <code>t.In</code> 不要钱。启动时加载一次。</p>'),
     ('TZ 会改变 Local', '<p>环境变量 <code>TZ</code> 为空串或 UTC 时 <code>time.Local</code> 是 UTC,设成地区名则按该地区。同一份程序在不同机器、不同容器里 <code>Local</code> 可能不同。</p>'),
     ('容器里的 tzdata', '<p>没有 <code>/usr/share/zoneinfo</code> 的最小镜像里,<code>LoadLocation("Asia/Shanghai")</code> 报 unknown time zone;编译时加 <code>-tags timetzdata</code>(或导入 <code>time/tzdata</code>)把数据库嵌进二进制,多 381 KiB。文档里的查找顺序也包括 <code>$GOROOT/lib/time/zoneinfo.zip</code> 与 <code>ZONEINFO</code> 环境变量。</p>')],
    steps,
    [ENV_G + '。夏令时与解析实验在 macOS 上用系统 /usr/share/zoneinfo;“容器里”的实验是把同一份源码交叉编译成 linux/arm64 静态程序(CGO_ENABLED=0),用 docker import 做成只含这一个文件的镜像,运行后已删除镜像;耗时用 testing.Benchmark;读过的文档:go doc time.LoadLocation',
     '没有验证:Linux 上系统时区库的路径差异、Windows 的行为、更多夏令时边缘(如半小时偏移的时区)、time/tzdata 的数据库版本是否最新、Format 的各个 layout 细节'],
    '时区与 time.Location')
